export type LvrtOraclePluginRequirements = ClientWithRpc<
  GetAccountInfoApi & GetMultipleAccountsApi
> &
  ClientWithPayer &
  ClientWithTransactionPlanning &
  ClientWithTransactionSending;

export function lvrtOracleProgram() {
  return <T extends LvrtOraclePluginRequirements>(
    client: T,
  ): ExtendedClient<T, { lvrtOracle: LvrtOraclePlugin }> => {
    return extendClient(client, {
      lvrtOracle: {
        accounts: {
          calendar: addSelfFetchFunctions(client, getCalendarCodec()),
          feed: addSelfFetchFunctions(client, getFeedCodec()),
          oracleConfig: addSelfFetchFunctions(client, getOracleConfigCodec()),
          priceState: addSelfFetchFunctions(client, getPriceStateCodec()),
          receiptRoot: addSelfFetchFunctions(client, getReceiptRootCodec()),
          signerKey: addSelfFetchFunctions(client, getSignerKeyCodec()),
        },
        instructions: {
          createFeed: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCreateFeedInstructionAsync({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          initialize: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitializeInstructionAsync({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          postChainlinkReport: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getPostChainlinkReportInstructionAsync(input),
            ),
          postPrices: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getPostPricesInstructionAsync(input),
            ),
          postReceiptRoot: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getPostReceiptRootInstructionAsync(input),
            ),
          postSwitchboardUpdate: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getPostSwitchboardUpdateInstructionAsync(input),
            ),
          registerSigner: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRegisterSignerInstructionAsync({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          revokeSigner: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRevokeSignerInstructionAsync(input),
            ),
          setCalendar: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetCalendarInstructionAsync(input),
            ),
          setStatus: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetStatusInstructionAsync(input),
            ),
          updateFeed: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getUpdateFeedInstructionAsync(input),
            ),
          verifyReceipt: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getVerifyReceiptInstruction(input),
            ),
        },
        pdas: {
          config: findConfigPda,
          calendar: findCalendarPda,
          signerKey: findSignerKeyPda,
          receipt: findReceiptPda,
        },
        identifyAccount: identifyLvrtOracleAccount,
        identifyInstruction: identifyLvrtOracleInstruction,
        parseInstruction: parseLvrtOracleInstruction,
      } as LvrtOraclePlugin,
    });
  };
}

type MakeOptional<T, K extends keyof T> = Omit<T, K> & Partial<Pick<T, K>>;
